async function ProcessRequest(info){
    var recive_status = 0;
    var ErrorMessage = "";
    var respData;
    // var apiHost = "http://localhost:8090/";
    var apiHost = "https://dev.telibrahma.in/";//"http://44.241.139.83:4003/";
    await fetch(apiHost + info.urlapi, {
        method: info.method,
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify(info.data)
    }).then(function(response) {
        // console.log(response)
        return response.json().catch(function(error){
            recive_status = 1;
            ErrorMessage = error.message;
            console.log(error)
        });
    }).then(function(resp_data) {
        respData = resp_data;
    }).catch(function(error){
        console.log(error)
        recive_status = 1;
        ErrorMessage = error.message;
    });
    if(recive_status === 1){
        return({respCode:5,respText:'Invalid Response: '+ErrorMessage});
    }else{
        return(respData);
    }
}
export default ProcessRequest;
