// clientPriority() still orders the queue internally; the visible badge is the backend "Sys #" rank.
const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const DAY_FULL = { Mon: 'MONDAY', Tue: 'TUESDAY', Wed: 'WEDNESDAY', Thu: 'THURSDAY', Fri: 'FRIDAY', Sat: 'SATURDAY', Sun: 'SUNDAY' };
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

// Reasons a rep must pick when rescheduling a planned visit (day/time change).
// Captured into the slot's moveHistory audit trail on confirmDrop.
const RESCHEDULE_REASONS = [
  'Customer not available',
  'Customer requested new date/time',
  'Prior commitment / schedule clash',
  'Travel / logistics issue',
  'Awaiting inputs / documents / approval',
  'Higher-priority visit came up',
  'Personal reason / leave'
];

const MAX_WEEK_OFFSET = 3; // current week + 3 future weeks
// Earliest navigable week offset (0 = current week; a negative value would allow past weeks).
const MIN_WEEK_OFFSET = 0;

// Week theme by offset; supports negative (past) offsets for the testing window above.
function weekThemeFor(offset) {
  if (offset >= 0) return WEEK_THEME[offset] || WEEK_THEME[WEEK_THEME.length - 1];
  return { label: offset === -1 ? 'Last Week' : `${-offset} Weeks Ago`, accent: '#8A6D3B' };
}

const WEEK_THEME = [
  { label: 'This Week', accent: '#534AB7' },
  { label: 'Next Week', accent: '#0277BD' },
  { label: '+2 Weeks',  accent: '#00838F' },
  { label: '+3 Weeks',  accent: '#2E7D32' },
];

// Duration slider: 30 min → 12 h (30-min steps). Reminder slider: Off → 3 h (15-min steps).
const DURATION_MIN = 30, DURATION_MAX = 720, DURATION_STEP = 30;
const REMINDER_MIN = 0,  REMINDER_MAX = 180, REMINDER_STEP = 15;
const DURATION_MARKS = [{ value: 60, label: '1h' }, { value: 360, label: '6h' }, { value: 720, label: '12h' }];
const REMINDER_MARKS = [{ value: 0, label: 'Off' }, { value: 60, label: '1h' }, { value: 180, label: '3h' }];

function fmtDurationLabel(mins) {
  const h = Math.floor(mins / 60), m = mins % 60;
  if (h && m) return `${h}h ${m}m`;
  if (h) return `${h}h`;
  return `${m}m`;
}
function fmtReminderLabel(mins) {
  return mins ? `${fmtDurationLabel(mins)} before` : 'No reminder';
}

// ── Helpers ─────────────────────────────────────────────────────────────────
function getMondayOfWeek(offset) {
  const today = new Date();
  const diff  = today.getDay() === 0 ? -6 : 1 - today.getDay();
  const mon   = new Date(today);
  mon.setDate(today.getDate() + diff + (offset || 0) * 7);
  mon.setHours(0, 0, 0, 0);
  return mon;
}

function formatWeekRange(monday) {
  const end = new Date(monday);
  end.setDate(monday.getDate() + 6);
  return `${MONTHS[monday.getMonth()]} ${monday.getDate()} – ${MONTHS[end.getMonth()]} ${end.getDate()}`;
}

function timeToMinutes(timeStr) {
  if (!timeStr) return 600;
  const m = timeStr.match(/(\d+):(\d+)\s*(AM|PM)/i);
  if (!m) return 600;
  let h = parseInt(m[1]);
  const min = parseInt(m[2]);
  const ap = m[3].toUpperCase();
  if (ap === 'PM' && h !== 12) h += 12;
  if (ap === 'AM' && h === 12) h = 0;
  return h * 60 + min;
}

// "14:30" → "2:30 PM"
function to12h(val) {
  if (!val) return '';
  const parts = val.split(':');
  const h = parseInt(parts[0]);
  const m = parts[1] || '00';
  const ap = h >= 12 ? 'PM' : 'AM';
  const hr = h % 12 === 0 ? 12 : h % 12;
  return `${hr}:${m} ${ap}`;
}

// "10:30 AM" → "10:30"
function to24h(display) {
  if (!display) return '09:00';
  const m = display.match(/(\d+):(\d+)\s*(AM|PM)/i);
  if (!m) return '09:00';
  let h = parseInt(m[1]);
  const ap = m[3].toUpperCase();
  if (ap === 'PM' && h !== 12) h += 12;
  if (ap === 'AM' && h === 12) h = 0;
  return `${String(h).padStart(2, '0')}:${m[2]}`;
}

// Value-weighted overall MF for a client: Σ(mf × value) / Σ(value).
// Offers with no MF set (mf ≤ 0) are excluded from BOTH sums, so a missing MF
// never drags the figure down. Returns 0 when no offer has an MF.
// Mirrors clientOverallMf() in the main app's SalesVisitPlanning page.
function clientOverallMf(offers) {
  let num = 0, den = 0;
  (offers || []).forEach((o) => {
    const mf = parseFloat(o.mf || 0);
    const v  = parseFloat(o.value || 0);
    if (mf > 0 && v > 0) { num += mf * v; den += v; }
  });
  return den > 0 ? num / den : 0;
}

// ── Component ─────────────────────────────────────────────────────────────────
class MyVisitPlan extends Component {
  constructor(props) {
    super(props);
    const q = new URLSearchParams(window.location.search);
    this.state = {
      userId:  q.get('userid'), // read from ?userid=<email> passed by the parent portal / Android
      loginid: q.get('checkin_id'),
      env:     q.get('env'),

      weekOffset:      0,
      planStatus:      'Draft',
      activeDay:       'Mon',
      searchText:      '',

      systemSuggested: [],
      otherClients:    [],
      queueLoading:    true,
      queueError:      '',

      scheduled:       { Mon: [], Tue: [], Wed: [], Thu: [], Fri: [], Sat: [], Sun: [] },
      slotCounter:     1,
      lastSaved:       null,
      planSaving:      false,

      // schedule dialog
      dropDialogOpen:        false,
      dropPendingOffer:      null,
      dropPendingDay:        null,
      dropPendingFromDay:    null,
      dropPendingFromSlotId: null,
      dropTime:              '10:00',
      dropDuration:          60,
      dropReminder:          15,
      dropVisitType:         'In-person',
      dropConflict:          '',
      dropReason:            '',   // reschedule reason (edit mode only)

      // client detail sheet
      detailClient: null,

      // add-visit dialog (single dialog: name, day, type, time, duration, reminder)
      addOpen:      false,
      addName:      '',
      allClientNames: [],  // full client list for the Add-Visit autocomplete (like CheckIn)
      allClients:     [],  // full client objects (id + name) → every not-yet-planned client
      addDay:       'Mon',
      addType:      'In-person',
      addTime:      '10:00',
      addDuration:  60,
      addReminder:  15,
      addConflict:  '',
      addSaving:    false,

      // add-client dialog (ported from CheckIn → tbl_temp_client_details)
      acOpen:            false,
      acName:            '',
      acPhone:           '',
      acContactPerson:   '',
      acCity:            '',
      acState:           '',
      acRegion:          '',
      acRegionsData:     [],
      acRegionsLoading:  false,
      acSaving:          false,

      // attendance / logout
      marking:    false,
      attendanceMarked: false, // red until marked this session, then green (resets on reload)
      LogoutFlag: false,

      // visit selection (for "check in to this visit")
      selectedSlotId: null,
      selectedDay:    null,

      // snackbar
      SnackBar: false, SnackBarVariant: 'warning', snackBarMessage: '', SnackbarTimeOut: 5000,

      // reusable confirmation dialog
      confirm: { open: false, title: '', message: '', confirmLabel: 'Confirm', cancelLabel: 'Cancel', danger: false, onConfirm: null },

      // Reminders dialog: every offer/debtor with a reminder_date set, grouped by client
      remindersDialog:    { open: false, loading: false, clients: [], error: '' },
      // Reschedule sub-dialog (date picker) for a single reminder row
      rescheduleReminder: { open: false, saving: false, item: null, newDate: '' },
    };
  }

  // ── Reusable confirm dialog ───────────────────────────────────────────────────
  askConfirm = (opts) => {
    this.setState({ confirm: { open: true, confirmLabel: 'Confirm', cancelLabel: 'Cancel', danger: false, onConfirm: null, ...opts } });
  }
  closeConfirm = () => this.setState((s) => ({ confirm: { ...s.confirm, open: false } }));
  handleConfirm = () => {
    const cb = this.state.confirm.onConfirm;
    this.closeConfirm();
    if (typeof cb === 'function') cb();
  }

  // Confirmation wrappers for the consequential actions on this page
  confirmSubmitToRM = () => {
    const { total } = this.getStats();
    this.askConfirm({
      title: 'Submit plan to RM?',
      message: `Submit this week's plan (${total} visit${total === 1 ? '' : 's'}) to your manager for approval? You won't be able to change it after submitting.`,
      confirmLabel: 'Submit',
      onConfirm: () => this.submitToRM(),
    });
  }
  confirmLogout = () => this.askConfirm({
    title: 'Log out?',
    message: 'Are you sure you want to log out?',
    confirmLabel: 'Log out',
    onConfirm: () => this.doLogout(),
  });
  confirmMarkAttendance = () => this.askConfirm({
    title: 'Mark attendance?',
    message: 'Mark your attendance at your current location now?',
    confirmLabel: 'Mark',
    onConfirm: () => this.markAttendance(),
  });
  confirmCheckin = () => {
    const slot = this.selectedSlot();
    if (!slot) return;
    const isCall = slot.type !== 'In-person';
    this.askConfirm({
      title: 'Start check-in?',
      message: isCall
        ? 'Please confirm your call with the customer is completed, and you are ready to update the call status.'
        : 'Please confirm you are ready to start your travel. We shall start tracking your travel route for conveyance reimbursement.',
      confirmLabel: 'Check in',
      onConfirm: () => this.goToCheckin(),
    });
  }

  async componentDidMount() {
    // Default the active day to today if it's a weekday, else Monday.
    const dow = new Date().getDay(); // 0 Sun .. 6 Sat
    this.setState({ activeDay: DAYS[dow === 0 ? 6 : dow - 1] }); // Sun→Sun, Mon..Sat→same
    await this.loadClientQueue();
    await this.loadPlan(this.getWeekStart());
    this.loadClientNames();
  }

  // Full client list for the Add-Visit autocomplete (same source as the CheckIn page).
  loadClientNames = async () => {
    const userid = this.state.userId;
    if (!userid) return;
    try {
      const resp = await ProcessRequest({ urlapi: 'salesvisit_stage/getClientDetails', method: 'POST', data: { userid } });
      if (resp && resp.respCode === 1 && Array.isArray(resp.clientdetails)) {
        const names = Array.from(new Set(resp.clientdetails.map((c) => c.client_name).filter(Boolean)));
        // Keep the full client objects too — id + name is enough to list every
        // not-yet-planned client in the unscheduled section and to schedule / de-dupe it.
        const allClients = resp.clientdetails
          .filter((c) => c.client_name)
          .map((c) => ({ clientId: c.id, clientName: c.client_name }));
        this.setState({ allClientNames: names, allClients });
      }
    } catch (err) { /* non-blocking: autocomplete just stays empty */ }
  }

  Snackbar = (variant, message, timeout) => {
    this.setState({ SnackBar: true, SnackBarVariant: variant, snackBarMessage: message, SnackbarTimeOut: timeout || 5000 });
  }

  // ── API ─────────────────────────────────────────────────────────────────────
  loadClientQueue = async () => {
    const email = this.state.userId;
    if (!email) { this.setState({ queueLoading: false, queueError: 'User not found. Please open from the app.' }); return; }
    try {
      this.setState({ queueLoading: true, queueError: '' });
      const resp = await ProcessRequest({ urlapi: 'salesvisit_stage/getClientQueue', method: 'POST', data: { email } });
      if (resp && resp.respCode === 1) {
        this.setState({ systemSuggested: resp.systemSuggested || [], otherClients: resp.otherClients || [], queueLoading: false });
      } else {
        this.setState({ queueLoading: false, queueError: (resp && resp.respText) || 'Failed to load client queue.' });
      }
    } catch (err) {
      this.setState({ queueLoading: false, queueError: err.message });
    }
  }

  getWeekStart() {
    const d = getMondayOfWeek(this.state.weekOffset);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  }

  loadPlan = async (weekStart) => {
    const email = this.state.userId;
    if (!email) return;
    try {
      const resp = await ProcessRequest({ urlapi: 'salesvisit_stage/getPlan', method: 'POST', data: { email, weekStart } });
      if (resp && resp.respCode === 1 && resp.plan) {
        const sched = resp.plan.scheduled || { Mon: [], Tue: [], Wed: [], Thu: [], Fri: [], Sat: [], Sun: [] };
        const status = resp.plan.planStatus || 'Draft';
        let maxId = 0;
        DAYS.forEach((d) => (sched[d] || []).forEach((s) => {
          // The backend approves a whole week's plan at once, so when it comes back Approved
          // every slot in it is approved. Otherwise honour each slot's own stored flag.
          if (status === 'Approved') s.approved = true;
          const n = parseInt((s.slotId || '').replace('s_', ''));
          if (!isNaN(n) && n > maxId) maxId = n;
        }));
        this.setState({ scheduled: sched, planStatus: status, slotCounter: maxId + 1 });
      } else {
        this.setState({ scheduled: { Mon: [], Tue: [], Wed: [], Thu: [], Fri: [], Sat: [], Sun: [] }, planStatus: 'Draft' });
      }
    } catch (err) {
      this.setState({ scheduled: { Mon: [], Tue: [], Wed: [], Thu: [], Fri: [], Sat: [], Sun: [] }, planStatus: 'Draft' });
    }
  }

  callSavePlan = async (status) => {
    if (this.state.planSaving) return;
    const email = this.state.userId;
    const weekStart = this.getWeekStart();
    this.setState({ planSaving: true });
    try {
      const resp = await ProcessRequest({
        urlapi: 'salesvisit_stage/savePlan', method: 'POST',
        data: { email, weekStart, scheduled: this.state.scheduled, planStatus: status },
      });
      if (resp && resp.respCode === 1) {
        this.setState({ planSaving: false, lastSaved: new Date(), planStatus: status });
        this.Snackbar('success', status === 'Submitted' ? 'Plan submitted to RM.' : 'Draft saved.', 4000);
      } else {
        this.setState({ planSaving: false });
        this.Snackbar('warning', (resp && resp.respText) || 'Could not save plan.', 5000);
      }
    } catch (err) {
      this.setState({ planSaving: false });
      this.Snackbar('warning', err.message, 5000);
    }
  }

  saveDraft  = () => this.callSavePlan('Draft');
  submitToRM = () => this.callSavePlan('Submitted');

  // ── Week nav ─────────────────────────────────────────────────────────────────
  prevWeek = () => {
    if (this.state.weekOffset <= MIN_WEEK_OFFSET) return;
    this.setState((s) => ({ weekOffset: s.weekOffset - 1 }), () => this.loadPlan(this.getWeekStart()));
  }
  nextWeek = () => {
    if (this.state.weekOffset >= MAX_WEEK_OFFSET) return;
    this.setState((s) => ({ weekOffset: s.weekOffset + 1 }), () => this.loadPlan(this.getWeekStart()));
  }

  getWeekDates() {
    const mon = getMondayOfWeek(this.state.weekOffset);
    return DAYS.map((day, i) => {
      const d = new Date(mon);
      d.setDate(mon.getDate() + i);
      return { day, date: d.getDate(), month: MONTHS[d.getMonth()] };
    });
  }

  // ── Derived priority (matches web) ──────────────────────────────────────────
  clientPriority(client) {
    const offers = client.offers || [];
    if (client.hasOverdueDebtors)                  return 'high';
    if (offers.some((o) => o.priority === 'high')) return 'high';
    if (client.totalDebtorAmount > 0)              return 'medium';
    if (offers.some((o) => o.priority === 'medium')) return 'medium';
    return 'low';
  }

  // clientIds already placed anywhere in the week
  scheduledClientIds() {
    const ids = new Set();
    DAYS.forEach((d) => (this.state.scheduled[d] || []).forEach((s) => ids.add(s.clientId)));
    return ids;
  }

  // Every master client that isn't in the pipeline queue and isn't already scheduled.
  // Shaped like a queue card (low priority, no offers/debtors) so it renders + schedules
  // exactly like a pipeline client — this is what surfaces the "yet to plan" clients.
  masterUnplannedClients() {
    const norm = (s) => String(s || '').trim().toLowerCase();
    const takenIds = new Set();
    const takenNames = new Set();
    this.state.systemSuggested.concat(this.state.otherClients).forEach((c) => {
      takenIds.add(String(c.clientId)); takenNames.add(norm(c.clientName));
    });
    DAYS.forEach((d) => (this.state.scheduled[d] || []).forEach((s) => {
      takenIds.add(String(s.clientId)); takenNames.add(norm(s.name || s.client));
    }));
    return (this.state.allClients || [])
      .filter((c) => c.clientName && !takenIds.has(String(c.clientId)) && !takenNames.has(norm(c.clientName)))
      .map((c) => ({
        clientId: c.clientId, clientName: c.clientName, type: 'In-person',
        offers: [], debtors: [], totalValue: 0, totalValueFormatted: '',
        hasOverdueDebtors: false, totalDebtorAmount: 0, maxExposure: 0, _isMaster: true,
      }));
  }

  // Unscheduled clients (pipeline queue + all other master clients), priority-sorted, filtered by search
  unscheduledClients() {
    const placed = this.scheduledClientIds();
    let list = this.state.systemSuggested.concat(this.state.otherClients).filter((c) => !placed.has(c.clientId));
    // Also list every other master client that hasn't been planned yet.
    list = list.concat(this.masterUnplannedClients());
    const q = this.state.searchText.trim().toLowerCase();
    if (q) {
      list = list.filter((c) =>
        (c.clientName || '').toLowerCase().includes(q) ||
        (c.offers || []).some((o) => (o.name || '').toLowerCase().includes(q)));
    }
    const rank = { high: 3, medium: 2, low: 1 };
    return list.slice().sort((a, b) => {
      const pr = (rank[this.clientPriority(b)] || 0) - (rank[this.clientPriority(a)] || 0);
      if (pr !== 0) return pr;
      const ex = (b.maxExposure || 0) - (a.maxExposure || 0);
      if (ex !== 0) return ex;
      return (a._isMaster ? 1 : 0) - (b._isMaster ? 1 : 0); // pipeline clients before bare master ones
    });
  }

  getStats() {
    const { scheduled } = this.state;
    let total = 0, visits = 0, calls = 0;
    DAYS.forEach((d) => (scheduled[d] || []).forEach((s) => {
      total++;
      if (s.type === 'In-person') visits++; else calls++;
    }));
    return { total, visits, calls, unscheduled: this.unscheduledClients().length };
  }

  // ── Scheduling ───────────────────────────────────────────────────────────────
  offerFromClient(client) {
    return {
      clientId: client.clientId, name: client.clientName, client: client.clientName,
      type: client.type || 'In-person', value: client.totalValueFormatted,
      priority: this.clientPriority(client), sysRank: client.sysRank,
      note: client.note, offers: client.offers, debtors: client.debtors,
      totalValueFormatted: client.totalValueFormatted, totalDebtorAmountFormatted: client.totalDebtorAmountFormatted,
    };
  }

  openScheduleForClient = (client) => {
    const offer = this.offerFromClient(client);
    this.setState({
      dropDialogOpen: true, dropPendingOffer: offer, dropPendingDay: this.clampToSelectableDay(this.state.activeDay),
      dropPendingFromDay: null, dropPendingFromSlotId: null,
      dropTime: '10:00', dropDuration: 60, dropReminder: 15,
      dropVisitType: offer.type || 'In-person', dropConflict: '', dropReason: '',
    });
  }

  openEditDialog = (slot, day) => {
    if (this.isVisitDone(slot)) {
      this.Snackbar('warning', 'This visit is already completed — it can no longer be rescheduled.', 4000);
      return;
    }
    this.setState({
      dropDialogOpen: true, dropPendingOffer: slot, dropPendingDay: this.clampToSelectableDay(day),
      dropPendingFromDay: day, dropPendingFromSlotId: slot.slotId,
      dropTime: to24h(slot.time), dropDuration: slot.duration || 60,
      dropReminder: slot.reminder !== undefined ? slot.reminder : 15,
      dropVisitType: slot.type || 'In-person', dropConflict: '', dropReason: '',
    });
  }

  cancelDrop = () => this.setState({ dropDialogOpen: false, dropPendingOffer: null, dropPendingDay: null, dropPendingFromDay: null, dropPendingFromSlotId: null, dropReason: '' });

  confirmDrop = async () => {
    const {
      dropPendingOffer, dropPendingDay, dropPendingFromDay, dropPendingFromSlotId,
      dropTime, dropDuration, dropReminder, dropVisitType, dropReason, scheduled, slotCounter,
    } = this.state;

    // In-person overlap check on the target day
    if (dropVisitType === 'In-person') {
      const newStart = timeToMinutes(to12h(dropTime));
      const newEnd   = newStart + dropDuration;
      const conflict = (scheduled[dropPendingDay] || []).find((s) => {
        if (s.type !== 'In-person') return false;
        if (s.slotId === dropPendingFromSlotId) return false;
        const sStart = timeToMinutes(s.time);
        const sEnd   = sStart + (s.duration || 60);
        return newStart < sEnd && newEnd > sStart;
      });
      if (conflict) {
        this.setState({ dropConflict: `"${conflict.name}" is already In-person at ${conflict.time} (${conflict.duration || 60} min). Choose a different time.` });
        return;
      }
    }

    const next = {};
    DAYS.forEach((d) => { next[d] = (scheduled[d] || []).slice(); });
    if (dropPendingFromDay && dropPendingFromSlotId) {
      next[dropPendingFromDay] = next[dropPendingFromDay].filter((s) => s.slotId !== dropPendingFromSlotId);
    }

    // On a reschedule (editing an existing slot), log the day/time change to the slot's
    // moveHistory so the backend keeps a full audit trail via savePlan.
    const isEdit  = Boolean(dropPendingFromSlotId);
    const newTime = to12h(dropTime);
    const prevHistory = (dropPendingOffer && dropPendingOffer.moveHistory) || [];
    const dayChanged  = isEdit && dropPendingFromDay !== dropPendingDay;
    const timeChanged = isEdit && dropPendingOffer && dropPendingOffer.time !== newTime;
    const rescheduled = isEdit && (dayChanged || timeChanged);
    // A reschedule (actual day/time change while editing) must carry a reason.
    if (rescheduled && !dropReason) {
      this.Snackbar('warning', 'Please select a reason for rescheduling.', 4000);
      return;
    }
    const history = rescheduled
      ? [...prevHistory, {
          action:   dayChanged ? 'Reschedule' : 'Time change',
          fromDay:  dropPendingFromDay, toDay: dropPendingDay,
          fromDate: this.dateForDay(dropPendingFromDay), toDate: this.dateForDay(dropPendingDay),
          fromTime: dropPendingOffer ? dropPendingOffer.time : '', toTime: newTime,
          reason:   dropReason,
          at:       new Date().toISOString(),
          by:       this.state.userId || '',
        }]
      : prevHistory;

    const slot = {
      ...dropPendingOffer,
      slotId: `s_${slotCounter}`, time: newTime,
      duration: dropDuration, reminder: dropReminder, type: dropVisitType,
      approved: false, // newly scheduled / rescheduled → pending approval (red) until the RM approves
      moveHistory: history,
      // Distinct field the backend can read directly (latest reschedule reason).
      // Set on an actual reschedule; otherwise the prior value carries over via the spread.
      ...(rescheduled ? { lastRescheduleReason: dropReason } : {}),
    };
    const daySlots = next[dropPendingDay].slice();
    daySlots.push(slot);
    daySlots.sort((a, b) => timeToMinutes(a.time) - timeToMinutes(b.time));
    next[dropPendingDay] = daySlots;

    await new Promise((resolve) => this.setState({
      scheduled: next, dropDialogOpen: false, dropPendingOffer: null, dropPendingDay: null,
      dropPendingFromDay: null, dropPendingFromSlotId: null, dropConflict: '', dropReason: '', slotCounter: slotCounter + 1,
    }, resolve));
    // Persist the edit/move/schedule so the plan is updated immediately.
    await this.callSavePlan(this.state.planStatus === 'Submitted' ? 'Submitted' : 'Draft');
  }

  // Calendar date (YYYY-MM-DD) for a day key in the currently-viewed week.
  dateForDay(day) {
    const mon = getMondayOfWeek(this.state.weekOffset);
    const d = new Date(mon);
    d.setDate(mon.getDate() + DAYS.indexOf(day));
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  }

  // True if the given day of the currently-viewed week falls before today's date.
  isPastDay(day) {
    const mon = getMondayOfWeek(this.state.weekOffset);
    const d = new Date(mon);
    d.setDate(mon.getDate() + DAYS.indexOf(day));
    d.setHours(0, 0, 0, 0);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return d < today;
  }

  // Days of the viewed week that can still be scheduled (today or later) — the
  // schedule/reschedule Day dropdown never offers a past date.
  selectableWeekDays() {
    return this.getWeekDates().filter((d) => !this.isPastDay(d.day));
  }

  // Default a schedule/reschedule target to a valid day: if `day` is in the past,
  // bump it to the first selectable (today-or-future) day of the viewed week.
  clampToSelectableDay(day) {
    if (!this.isPastDay(day)) return day;
    const first = this.selectableWeekDays()[0];
    return first ? first.day : day;
  }

  // ── "Today" helpers ──────────────────────────────────────────────────────────
  // The weekday key (Mon..Sun) for the real current date.
  todayDayKey() {
    const dow = new Date().getDay(); // 0 Sun .. 6 Sat
    return DAYS[dow === 0 ? 6 : dow - 1];
  }
  // A slot is checkable only if it sits on today's date — i.e. the current week
  // (weekOffset 0) AND its day matches today. Reps may plan any day, but may only
  // select + check in to visits scheduled for today.
  isTodaySlot(day) {
    return this.state.weekOffset === 0 && day === this.todayDayKey();
  }

  // A visit is "done" once its outcome has been recorded by the backend: a Call gets a
  // callOutcome; an In-person visit gets discussionType/discussionNotes; either way an
  // outcomeBy is stamped. A completed visit can't be preponed/postponed/rescheduled.
  isVisitDone(slot) {
    const has = (v) => v !== undefined && v !== null && String(v).trim() !== '';
    return has(slot.callOutcome) || has(slot.discussionType) || has(slot.discussionNotes) || has(slot.outcomeBy);
  }

  // ── Select a visit → check in ────────────────────────────────────────────────
  toggleSelectSlot = (day, slot) => {
    if (!this.isTodaySlot(day)) {
      this.Snackbar('warning', 'You can only check in to visits scheduled for today.', 4000);
      return;
    }
    if (this.state.selectedSlotId === slot.slotId) {
      this.setState({ selectedSlotId: null, selectedDay: null });
    } else {
      this.setState({ selectedSlotId: slot.slotId, selectedDay: day });
    }
  }

  selectedSlot = () => {
    const { selectedSlotId, selectedDay, scheduled } = this.state;
    if (!selectedSlotId || !selectedDay) return null;
    return (scheduled[selectedDay] || []).find((s) => s.slotId === selectedSlotId) || null;
  }

  goToCheckin = () => {
    const slot = this.selectedSlot();
    if (!slot) return;
    const params = new URLSearchParams();
    params.set('client', slot.name || slot.client || '');
    if (slot.clientId) params.set('clientId', slot.clientId);
    params.set('locked', '1');
    // Interlink: tie this check-in back to the planned slot (email|week_start|slotId).
    if (slot.slotId) params.set('planned_visit_id', `${this.state.userId}|${this.getWeekStart()}|${slot.slotId}`);
    // Carry the visit type through so downstream knows Call vs In-person.
    params.set('visit', slot.type === 'In-person' ? 'inperson' : 'Call');
    // Only a Call auto-checks-in (skips the form); In-person opens the check-in form.
    if (slot.type !== 'In-person') {
      params.set('auto', '1');
    }
    if (this.state.userId) params.set('userid', this.state.userId);
    if (this.state.loginid) params.set('checkin_id', this.state.loginid);
    if (this.state.env) params.set('env', this.state.env);
    // Signal URL for the Android webview: Android intercepts "/salesvisit_stage/plancheckin",
    // reads these query params, and relaunches CheckIn.js natively with the same param names
    // (client, clientId, locked, auto, visit, planned_visit_id, userid, checkin_id, env) so the
    // client is pre-filled/locked and the id references are carried through.
    window.location.href = '/salesvisit_stage/plancheckin?' + params.toString();
  }

  // ── Add Visit (single dialog: name, day, type, time, duration, reminder) ──────
  openAdd  = () => this.setState({
    addOpen: true, addName: '', addDay: this.clampToSelectableDay(this.state.activeDay), addType: 'In-person',
    addTime: '10:00', addDuration: 60, addReminder: 15, addConflict: '', addSaving: false,
  });
  cancelAdd = () => this.setState({ addOpen: false });

  confirmAdd = async () => {
    const { addName, addDay, addType, addTime, addDuration, addReminder, scheduled, slotCounter } = this.state;
    const name = addName.trim();
    if (!name) { this.Snackbar('warning', 'Please enter a client name.', 4000); return; }

    // In-person overlap check on the chosen day
    if (addType === 'In-person') {
      const newStart = timeToMinutes(to12h(addTime));
      const newEnd   = newStart + addDuration;
      const conflict = (scheduled[addDay] || []).find((s) => {
        if (s.type !== 'In-person') return false;
        const sStart = timeToMinutes(s.time);
        return newStart < (sStart + (s.duration || 60)) && newEnd > sStart;
      });
      if (conflict) {
        this.setState({ addConflict: `"${conflict.name}" is already In-person at ${conflict.time} (${conflict.duration || 60} min). Choose a different time.` });
        return;
      }
    }

    const slot = {
      clientId: `custom_${slotCounter}`, name, client: name, offers: [], debtors: [],
      slotId: `s_${slotCounter}`, time: to12h(addTime),
      duration: addDuration, reminder: addReminder, type: addType, priority: 'low', value: '',
      approved: false, // newly added → pending approval (red) until the RM approves
    };
    const next = {};
    DAYS.forEach((d) => { next[d] = (scheduled[d] || []).slice(); });
    next[addDay] = next[addDay].concat(slot).sort((a, b) => timeToMinutes(a.time) - timeToMinutes(b.time));

    // Add to the plan, then persist so the selected day's plan is updated.
    await new Promise((resolve) => this.setState({
      scheduled: next, slotCounter: slotCounter + 1, addOpen: false, addConflict: '',
    }, resolve));
    await this.callSavePlan(this.state.planStatus === 'Submitted' ? 'Submitted' : 'Draft');
  }

  // ── Add Client (ported from CheckIn → tbl_temp_client_details) ────────────────
  openAddClient = () => {
    this.setState({
      acOpen: true, acName: '', acPhone: '', acContactPerson: '',
      acCity: '', acState: '', acRegion: '', acSaving: false,
    });
    this.fetchAcRegions();
  }
  cancelAddClient = () => this.setState({ acOpen: false });

  fetchAcRegions = async () => {
    if (this.state.acRegionsData.length > 0) return;
    this.setState({ acRegionsLoading: true });
    const resp = await ProcessRequest({ urlapi: 'salesvisit_stage/getRegions', method: 'POST', data: { userid: this.state.userId } });
    if (resp && resp.respCode === 1) this.setState({ acRegionsData: Array.isArray(resp.regions) ? resp.regions : [] });
    else this.Snackbar('warning', (resp && resp.respText) || 'Unable to load regions.', 5000);
    this.setState({ acRegionsLoading: false });
  }

  saveNewClient = async () => {
    const name    = this.state.acName.trim();
    const phone   = this.state.acPhone.trim();
    const contact = this.state.acContactPerson.trim();
    const city    = this.state.acCity.trim();
    const stateNm = this.state.acState.trim();
    const region  = this.state.acRegion;
    if (!name)                { this.Snackbar('warning', 'Please enter Client Name.', 4000); return; }
    if (!/^\d{10}$/.test(phone)) { this.Snackbar('warning', 'Please enter a valid 10-digit Phone Number.', 4000); return; }
    if (!contact)             { this.Snackbar('warning', 'Please enter Contact Person Name.', 4000); return; }
    if (!city)                { this.Snackbar('warning', 'Please enter City.', 4000); return; }
    if (!stateNm)             { this.Snackbar('warning', 'Please enter State.', 4000); return; }
    if (!region)              { this.Snackbar('warning', 'Please select Region.', 4000); return; }

    this.setState({ acSaving: true });
    const resp = await ProcessRequest({
      urlapi: 'salesvisit_stage/saveTempClientDetails', method: 'POST',
      data: {
        client_name: name, phone_number: phone, contact_person: contact,
        city: city, state: stateNm, region: region,
        loginid: this.state.loginid, userid: this.state.userId,
      },
    });
    if (resp && resp.respCode === 1 && resp.respText === 'success') {
      // Add locally so the new (unapproved) client shows up right away in the Add-Visit
      // autocomplete and the unscheduled list, without waiting for a reload/refetch.
      const newEntry = { clientId: `temp_${Date.now()}`, clientName: name };
      this.setState((s) => ({
        acOpen: false, acSaving: false,
        allClients: [newEntry, ...s.allClients],
        allClientNames: s.allClientNames.includes(name) ? s.allClientNames : [name, ...s.allClientNames],
      }));
      this.Snackbar('success', 'New client saved.', 4000);
    } else {
      this.setState({ acSaving: false });
      this.Snackbar('warning', resp ? resp.respText : 'Server not responding.', 5000);
    }
  }

  // ── Reminders: every offer/debtor with a reminder_date set, across ALL of the
  // rep's open offers/debtors (not just the ranked queue), grouped by client. ──
  openReminders = async () => {
    const email = this.state.userId;
    this.setState({ remindersDialog: { open: true, loading: true, clients: [], error: '' } });
    try {
      const resp = await ProcessRequest({ urlapi: 'salesvisit_stage/getReminders', method: 'POST', data: { email } });
      if (resp && resp.respCode === 1) {
        this.setState({ remindersDialog: { open: true, loading: false, clients: resp.clients || [], error: '' } });
      } else {
        this.setState({ remindersDialog: { open: true, loading: false, clients: [], error: (resp && resp.respText) || 'Could not load reminders.' } });
      }
    } catch (e) {
      this.setState({ remindersDialog: { open: true, loading: false, clients: [], error: e.message } });
    }
  }
  closeReminders = () => this.setState((s) => ({ remindersDialog: { ...s.remindersDialog, open: false } }));

  // Reschedule: available on every reminder (not just overdue). Opens a small
  // date-picker sub-dialog; only the reminder date changes, nothing else.
  openRescheduleReminder = (item) => {
    const minDate = new Date().toISOString().slice(0, 10);
    this.setState({ rescheduleReminder: { open: true, saving: false, item, newDate: minDate } });
  }
  closeRescheduleReminder = () => this.setState({ rescheduleReminder: { open: false, saving: false, item: null, newDate: '' } });

  confirmRescheduleReminder = async () => {
    const { item, newDate } = this.state.rescheduleReminder;
    if (!item || !newDate) return;
    this.setState((s) => ({ rescheduleReminder: { ...s.rescheduleReminder, saving: true } }));
    try {
      const resp = await ProcessRequest({
        urlapi: 'salesvisit_stage/updateReminder', method: 'POST',
        data: {
          type: item.type, action: 'reschedule',
          clientId: item.clientId, clientName: item.clientName, refNo: item.refNo,
          oldReminderDate: item.reminderDate, nextAction: item.nextAction, remarks: item.remarks,
          newDate, performedBy: this.state.userId,
        },
      });
      if (resp && resp.respCode === 1) {
        this.closeRescheduleReminder();
        this.Snackbar('success', 'Reminder rescheduled.', 3000);
        this.openReminders(); // refresh the list with the new date reflected
      } else {
        this.setState((s) => ({ rescheduleReminder: { ...s.rescheduleReminder, saving: false } }));
        this.Snackbar('warning', (resp && resp.respText) || 'Could not reschedule the reminder.', 5000);
      }
    } catch (e) {
      this.setState((s) => ({ rescheduleReminder: { ...s.rescheduleReminder, saving: false } }));
      this.Snackbar('warning', e.message, 5000);
    }
  }

  // Close: clears the reminder date so the item drops out of this dialog; the
  // action + prior date are preserved in tbl_salesvisit_reminder_history.
  closeReminderItem = (item) => {
    this.askConfirm({
      title: 'Close this reminder?',
      message: `Close the reminder for ${item.refNo}? It will no longer appear here.`,
      confirmLabel: 'Close reminder',
      onConfirm: async () => {
        try {
          const resp = await ProcessRequest({
            urlapi: 'salesvisit_stage/updateReminder', method: 'POST',
            data: {
              type: item.type, action: 'close',
              clientId: item.clientId, clientName: item.clientName, refNo: item.refNo,
              oldReminderDate: item.reminderDate, nextAction: item.nextAction, remarks: item.remarks,
              performedBy: this.state.userId,
            },
          });
          if (resp && resp.respCode === 1) {
            this.Snackbar('success', 'Reminder closed.', 3000);
            this.openReminders(); // refresh — the closed item will no longer be returned
          } else {
            this.Snackbar('warning', (resp && resp.respText) || 'Could not close the reminder.', 5000);
          }
        } catch (e) {
          this.Snackbar('warning', e.message, 5000);
        }
      },
    });
  }

  // ── Attendance / Logout (geo) ─────────────────────────────────────────────────
  withGeo(cb) {
    if (!navigator.geolocation) { cb('NA', 'NA'); return; }
    navigator.geolocation.getCurrentPosition(
      (p) => cb(p.coords.latitude, p.coords.longitude),
      () => cb('NA', 'NA')
    );
  }

  markAttendance = () => {
    if (this.state.marking) return;
    this.setState({ marking: true });
    this.withGeo(async (lat, long) => {
      try {
        const resp = await ProcessRequest({ urlapi: 'salesvisit_stage/markAttendance', method: 'POST', data: { username: this.state.userId, latitude: lat, longitude: long } });
        if (resp && resp.respCode === 1) { this.setState({ attendanceMarked: true }); this.Snackbar('success', 'Attendance marked.', 4000); }
        else this.Snackbar('warning', (resp && resp.respText) || 'Could not mark attendance.', 5000);
      } catch (e) { this.Snackbar('warning', e.message, 5000); }
      this.setState({ marking: false });
    });
  }

  doLogout = () => {
    this.withGeo(async (lat, long) => {
      try {
        await ProcessRequest({ urlapi: 'salesvisit_stage/insertLogoutLog', method: 'POST', data: { username: this.state.userId, latitude: lat, longitude: long } });
      } catch (e) { /* ignore — still log the user out */ }
      this.setState({ LogoutFlag: true });
    });
  }

  goBack = () => { window.history.back(); }

  // ─── Render: top bar ────────────────────────────────────────────────────────
  renderTopBar() {
    const { planStatus, weekOffset } = this.state;
    const monday = getMondayOfWeek(weekOffset);
    const theme  = weekThemeFor(weekOffset);
    const statusStyle =
      planStatus === 'Draft'     ? { bg: '#FFF8EE', color: C.med,   border: C.med   } :
      planStatus === 'Submitted' ? { bg: '#EEEAFF', color: C.brand, border: C.brand } :
                                   { bg: '#EAF3DE', color: C.low,   border: C.low   };
    return (
      <Paper elevation={2} sx={{ borderRadius: 0, flexShrink: 0, zIndex: 3 }}>
        <Box sx={{ px: 1.5, py: 1, display: 'flex', alignItems: 'center', gap: 0.5 }}>
          <IconButton size="small" onClick={this.goBack}><ArrowBack fontSize="small" /></IconButton>
          <Typography variant="subtitle1" fontWeight={700} noWrap sx={{ flex: 1, fontSize: 15 }}>My visit plan</Typography>
          <IconButton size="small" onClick={this.openReminders} title="Reminders" sx={{ color: C.med }}><NotificationsActive fontSize="small" /></IconButton>
          <IconButton size="small" onClick={this.confirmLogout} title="Logout" sx={{ color: '#888' }}><LogoutIcon fontSize="small" /></IconButton>
        </Box>

        {/* Primary actions — kept big & obvious so reps never miss them */}
        <Box sx={{ px: 1.5, pb: 1, display: 'flex', gap: 1 }}>
          <Button
            onClick={this.openAdd}
            startIcon={<AddLocationAlt sx={{ fontSize: 22 }} />}
            sx={{
              flex: 1, py: 1, borderRadius: 999, textTransform: 'none',
              fontSize: 14, fontWeight: 800, color: '#fff', letterSpacing: 0.2,
              background: `linear-gradient(135deg, ${C.brand} 0%, #3B3391 100%)`,
              boxShadow: '0 4px 12px rgba(83,74,183,0.40)',
              animation: 'addPulse 2.4s ease-in-out infinite',
              '@keyframes addPulse': {
                '0%':   { boxShadow: '0 4px 12px rgba(83,74,183,0.40)' },
                '50%':  { boxShadow: '0 4px 20px rgba(83,74,183,0.70)' },
                '100%': { boxShadow: '0 4px 12px rgba(83,74,183,0.40)' },
              },
              '&:hover': { background: `linear-gradient(135deg, #4A42A6 0%, #322B82 100%)` },
              '&:active': { transform: 'translateY(1px)' },
            }}
          >
            Add Visit
          </Button>
          <Button
            onClick={this.openAddClient}
            startIcon={<PersonAdd sx={{ fontSize: 22 }} />}
            sx={{
              flex: 1, py: 1, borderRadius: 999, textTransform: 'none',
              fontSize: 14, fontWeight: 800, color: C.brand, letterSpacing: 0.2,
              bgcolor: `${C.brand}14`,
              border: `1.5px solid ${C.brand}`,
              boxShadow: 'none',
              '&:hover': { bgcolor: `${C.brand}22` },
              '&:active': { transform: 'translateY(1px)' },
            }}
          >
            Add Client
          </Button>
        </Box>
        <Box sx={{ px: 1.5, pb: 1, display: 'flex', alignItems: 'center', gap: 1 }}>
          <IconButton size="small" onClick={this.prevWeek} disabled={weekOffset <= MIN_WEEK_OFFSET}><NavigateBefore fontSize="small" /></IconButton>
          <Box sx={{ flex: 1, textAlign: 'center' }}>
            <Typography sx={{ fontSize: 13, fontWeight: 600, color: '#333', lineHeight: 1.2 }}>{formatWeekRange(monday)}</Typography>
            <Typography sx={{ fontSize: 10, fontWeight: 700, color: theme.accent }}>{theme.label}</Typography>
          </Box>
          <IconButton size="small" onClick={this.nextWeek} disabled={weekOffset >= MAX_WEEK_OFFSET}><NavigateNext fontSize="small" /></IconButton>
          <Chip label={planStatus} size="small" sx={{ bgcolor: statusStyle.bg, color: statusStyle.color, border: `1px solid ${statusStyle.border}`, fontWeight: 700, fontSize: 11 }} />
        </Box>
      </Paper>
    );
  }

  // ─── Render: day strip ──────────────────────────────────────────────────────
  renderDayStrip() {
    const { activeDay, scheduled, weekOffset } = this.state;
    const theme = weekThemeFor(weekOffset);
    const dates = this.getWeekDates();
    return (
      <Box sx={{ display: 'flex', gap: 0.8, px: 1.5, py: 1, overflowX: 'auto', flexShrink: 0, bgcolor: '#fafafa', borderBottom: '1px solid #eee' }}>
        {dates.map(({ day, date }) => {
          const count    = (scheduled[day] || []).length;
          const selected = activeDay === day;
          return (
            <Box key={day} onClick={() => this.setState({ activeDay: day })}
              sx={{
                minWidth: 60, flex: '0 0 auto', textAlign: 'center', py: 0.8, borderRadius: 2, cursor: 'pointer',
                border: `1.5px solid ${selected ? theme.accent : '#e0e0e0'}`,
                bgcolor: selected ? `${theme.accent}12` : 'white',
              }}>
              <Typography sx={{ fontSize: 10, fontWeight: 700, color: selected ? theme.accent : '#999', textTransform: 'uppercase' }}>{day}</Typography>
              <Typography sx={{ fontSize: 18, fontWeight: 800, lineHeight: 1.1, color: selected ? theme.accent : '#333' }}>{date}</Typography>
              <Typography sx={{ fontSize: 9, color: count ? C.brand : '#bbb', fontWeight: 600 }}>{count ? `${count} plan${count > 1 ? 's' : ''}` : '—'}</Typography>
            </Box>
          );
        })}
      </Box>
    );
  }

  // ─── Render: the backend "Sys #N" rank badge — shown only when the client is system-ranked ─
  renderSysTag(sysRank) {
    if (!sysRank) return null;
    return (
      <Box sx={{ display: 'inline-flex', alignItems: 'center', px: 0.8, height: 18, borderRadius: 999, bgcolor: C.sysBadgeBg, border: `1px solid ${C.inPersonBorder}` }}>
        <Typography sx={{ fontSize: 9.5, fontWeight: 800, color: C.sysBadgeText }}>Sys #{sysRank}</Typography>
      </Box>
    );
  }

  // ─── Render: one scheduled card (planned → green) ───────────────────────────
  renderScheduledCard(slot, day) {
    const ip = slot.type === 'In-person';
    const selected = this.state.selectedSlotId === slot.slotId;
    // Green once this specific visit is approved; red while it's added-but-pending approval.
    // Per-slot (not plan-wide) so adding one visit doesn't turn previously-approved ones red.
    // loadPlan() stamps approved:true on every slot when the whole plan comes back Approved.
    const approved = slot.approved === true;
    // A completed visit is locked: no prepone / postpone / reschedule.
    const done = this.isVisitDone(slot);
    const cs = approved
      ? { bg: C.plannedBg, border: C.plannedBorder, accent: C.plannedAccent, selBg: C.plannedSelBg }
      : { bg: C.pendingBg, border: C.pendingBorder, accent: C.pendingAccent, selBg: C.pendingSelBg };
    return (
      <React.Fragment key={slot.slotId}>
      <Paper elevation={0}
        onClick={() => this.toggleSelectSlot(day, slot)}
        sx={{ display: 'flex', mb: selected ? 0.5 : 0.8, borderRadius: 1.5, cursor: 'pointer', overflow: 'hidden',
          border: selected ? `2px solid ${cs.accent}` : `1px solid ${cs.border}`,
          bgcolor: selected ? cs.selBg : cs.bg, '&:active': { bgcolor: cs.selBg } }}>
        <Box sx={{ width: 4, flexShrink: 0, bgcolor: cs.accent }} />
        <Box sx={{ p: 1, flex: 1, minWidth: 0 }}>
          <Box sx={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 0.5 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, minWidth: 0 }}>
              {selected && <HowToReg sx={{ fontSize: 15, color: C.brand, flexShrink: 0 }} />}
              <Typography sx={{ fontSize: 12, fontWeight: 700, color: '#222', lineHeight: 1.3 }}>{slot.name}</Typography>
            </Box>
            <Box sx={{ display: 'flex', gap: 0.2, flexShrink: 0 }}>
              {(slot.offers && slot.offers.length > 0) || (slot.debtors && slot.debtors.length > 0) ? (
                <IconButton size="small" sx={{ p: '2px' }} onClick={(e) => { e.stopPropagation(); this.setState({ detailClient: slot }); }} title="Client detail"><Business sx={{ fontSize: 15, color: C.brand }} /></IconButton>
              ) : null}
              <IconButton size="small" sx={{ p: '2px' }} disabled={done} onClick={(e) => { e.stopPropagation(); this.openEditDialog(slot, day); }} title={done ? 'Completed — can’t reschedule' : 'Reschedule'}><AccessTime sx={{ fontSize: 15, color: '#888' }} /></IconButton>
            </Box>
          </Box>
          {slot.client && slot.client !== slot.name && (
            <Typography sx={{ fontSize: 10.5, color: '#888' }} noWrap>{slot.client}</Typography>
          )}
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.8, mt: 0.5, flexWrap: 'wrap' }}>
            {this.renderSysTag(slot.sysRank)}
            {done && (
              <Chip size="small" icon={<HowToReg sx={{ fontSize: '12px !important', color: `${C.low} !important` }} />} label="Done"
                sx={{ height: 20, fontSize: 10, fontWeight: 800, bgcolor: C.plannedBg, color: C.low, border: `1px solid ${C.plannedBorder}`, '& .MuiChip-label': { px: 0.7 } }} />
            )}
            <Chip size="small"
              icon={ip ? <LocationOn sx={{ fontSize: '12px !important', color: `${C.sysBadgeText} !important` }} /> : <Phone sx={{ fontSize: '12px !important', color: '#1a5276 !important' }} />}
              label={`${slot.time} · ${slot.duration || 60}m · ${ip ? 'In-person' : 'Call'}`}
              sx={{ height: 20, fontSize: 10, fontWeight: 600, bgcolor: ip ? C.inPersonBg : C.callBg, color: ip ? C.sysBadgeText : '#1a5276', border: `1px solid ${ip ? C.inPersonBorder : C.callBorder}`, '& .MuiChip-label': { px: 0.7 } }} />
            {slot.value ? <Typography sx={{ fontSize: 10.5, fontWeight: 700, color: C.brand }}>{slot.value}</Typography> : null}
            {slot.reminder > 0 && (
              <Typography sx={{ fontSize: 9.5, color: '#aaa', display: 'flex', alignItems: 'center', gap: 0.2 }}>
                <NotificationsNone sx={{ fontSize: 11 }} />{slot.reminder}m
              </Typography>
            )}
            {slot.moveHistory && slot.moveHistory.length > 0 && (
              <Typography
                title={slot.moveHistory.map((h) => {
                  const when = h.at ? ` (${new Date(h.at).toLocaleString('en-IN')})` : '';
                  const why  = h.reason ? ` · ${h.reason}` : '';
                  return h.action === 'Time change'
                    ? `Time change: ${h.fromTime || ''} → ${h.toTime || ''}${why}${when}`
                    : `${h.action}: ${h.fromDate} → ${h.toDate}${why}${when}`;
                }).join('\n')}
                sx={{ fontSize: 9.5, fontWeight: 700, color: C.med, display: 'flex', alignItems: 'center', gap: 0.2 }}>
                <AccessTime sx={{ fontSize: 11 }} />moved ×{slot.moveHistory.length}
              </Typography>
            )}
          </Box>
        </Box>
      </Paper>
      {selected && (
        <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 1 }}>
          <Button variant="contained" size="small" onClick={this.confirmCheckin} endIcon={<NavigateNext />}
            sx={{ textTransform: 'none', bgcolor: C.brand, '&:hover': { bgcolor: '#3d35a0' }, fontSize: 12, fontWeight: 700, borderRadius: 1.5, px: 2 }}>
            Check in
          </Button>
        </Box>
      )}
      </React.Fragment>
    );
  }

  // ─── Render: day sections (all days) ────────────────────────────────────────
  renderDaySections() {
    const { scheduled, activeDay } = this.state;
    const dates = this.getWeekDates();
    return dates.map(({ day, date, month }) => {
      const slots = (scheduled[day] || []).slice().sort((a, b) => timeToMinutes(a.time) - timeToMinutes(b.time));
      const isActive = activeDay === day;
      const isToday  = this.isTodaySlot(day);
      return (
        <Box key={day} sx={{ mb: 1.5 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.8, mb: 0.6 }}>
            <Typography sx={{ fontSize: 11, fontWeight: 800, color: isActive ? C.brand : '#999', textTransform: 'uppercase', letterSpacing: 0.5 }}>
              {DAY_FULL[day]}, {month} {date}
            </Typography>
            {isToday && (
              <Chip label="TODAY · CHECK-IN" size="small"
                sx={{ height: 16, fontSize: 8.5, fontWeight: 800, letterSpacing: 0.3, bgcolor: C.plannedBg, color: C.plannedAccent, border: `1px solid ${C.plannedBorder}`, '& .MuiChip-label': { px: 0.7 } }} />
            )}
          </Box>
          {slots.length > 0
            ? slots.map((s) => this.renderScheduledCard(s, day))
            : (
              <Box onClick={() => this.setState({ activeDay: day }, () => this.openAdd())}
                sx={{ border: '1px dashed #d5d5d5', borderRadius: 1.5, py: 1.2, textAlign: 'center', cursor: 'pointer', color: '#bbb', fontSize: 11, bgcolor: isActive ? `${C.brand}08` : 'transparent' }}>
                + No visit planned — tap to add
              </Box>
            )}
        </Box>
      );
    });
  }

  // ─── Render: unscheduled offers ─────────────────────────────────────────────
  renderUnscheduled() {
    const list = this.unscheduledClients();
    const searching = this.state.searchText.trim().length > 0;
    const RENDER_CAP = 60; // don't paint hundreds of cards on mobile; search reveals the rest
    const shown = searching ? list : list.slice(0, RENDER_CAP);
    const hiddenCount = list.length - shown.length;
    const dates = this.getWeekDates();
    const active = dates.find((d) => d.day === this.state.activeDay);
    const activeLabel = active ? `${active.day}, ${active.month} ${active.date}` : this.state.activeDay;
    return (
      <Box sx={{ mt: 1 }}>
        <Divider sx={{ mb: 1 }} />
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 0.8 }}>
          <Typography sx={{ fontSize: 11, fontWeight: 800, color: '#666', textTransform: 'uppercase', letterSpacing: 0.4 }}>Unscheduled clients</Typography>
          <Typography sx={{ fontSize: 10, color: C.brand, fontWeight: 600 }}>tap to add to {activeLabel}</Typography>
        </Box>
        <TextField size="small" fullWidth placeholder="Search client or project…"
          value={this.state.searchText} onChange={(e) => this.setState({ searchText: e.target.value })}
          sx={{ mb: 1, '& .MuiInputBase-input': { fontSize: 12, py: '6px' }, '& .MuiOutlinedInput-root': { borderRadius: 1.5 } }} />
        {list.length === 0 ? (
          <Typography sx={{ fontSize: 11, color: '#bbb', textAlign: 'center', py: 2 }}>Nothing pending — all clients scheduled 🎉</Typography>
        ) : shown.map((client, idx) => {
          const ip = client.type === 'In-person';
          return (
            <Paper key={`u_${client.clientId}_${idx}`} elevation={0}
              onClick={() => this.openScheduleForClient(client)}
              sx={{ display: 'flex', mb: 0.8, borderRadius: 1.5, border: `1px solid ${C.unplannedBorder}`, bgcolor: C.unplannedBg, overflow: 'hidden', cursor: 'pointer', '&:active': { bgcolor: '#FDEBD6' } }}>
              <Box sx={{ width: 4, flexShrink: 0, bgcolor: C.unplannedAccent }} />
              <Box sx={{ p: 1, flex: 1, minWidth: 0 }}>
                <Box sx={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 0.5 }}>
                  <Typography sx={{ fontSize: 12, fontWeight: 700, color: '#222', lineHeight: 1.3 }}>{client.clientName}</Typography>
                  {(client.offers && client.offers.length > 0) || (client.debtors && client.debtors.length > 0) ? (
                    <IconButton size="small" sx={{ p: '2px' }} onClick={(e) => { e.stopPropagation(); this.setState({ detailClient: this.offerFromClient(client) }); }} title="Client detail"><Business sx={{ fontSize: 15, color: C.brand }} /></IconButton>
                  ) : null}
                </Box>
                {(client.offers || []).slice(0, 1).map((o) => (
                  <Typography key={o.id} sx={{ fontSize: 10.5, color: '#888' }} noWrap>📄 {o.name}</Typography>
                ))}
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.8, mt: 0.5, flexWrap: 'wrap' }}>
                  {this.renderSysTag(client.sysRank)}
                  <Chip size="small"
                    icon={ip ? <LocationOn sx={{ fontSize: '12px !important', color: `${C.sysBadgeText} !important` }} /> : <Phone sx={{ fontSize: '12px !important', color: '#1a5276 !important' }} />}
                    label={ip ? 'In-person' : 'Call'}
                    sx={{ height: 19, fontSize: 10, fontWeight: 600, bgcolor: ip ? C.inPersonBg : C.callBg, color: ip ? C.sysBadgeText : '#1a5276', border: `1px solid ${ip ? C.inPersonBorder : C.callBorder}`, '& .MuiChip-label': { px: 0.6 } }} />
                  {client.totalValue > 0 && <Typography sx={{ fontSize: 10.5, fontWeight: 700, color: C.brand }}>{client.totalValueFormatted}</Typography>}
                  {client.hasOverdueDebtors && <Chip label="overdue" size="small" sx={{ height: 18, fontSize: 9.5, fontWeight: 700, bgcolor: '#FEEDED', color: '#B71C1C', border: '1px solid #F5C6C6', '& .MuiChip-label': { px: 0.6 } }} />}
                </Box>
              </Box>
            </Paper>
          );
        })}
        {hiddenCount > 0 && (
          <Typography sx={{ fontSize: 10.5, color: '#999', textAlign: 'center', py: 1 }}>
            +{hiddenCount} more client{hiddenCount > 1 ? 's' : ''} — type a name above to search all
          </Typography>
        )}
      </Box>
    );
  }

  // ─── Render: schedule dialog ────────────────────────────────────────────────
  // Duration / Reminder sliders — shared by the Schedule/Edit and Add-Visit dialogs
  renderDurationSlider(value, onChange) {
    return (
      <Box>
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 0.5 }}>
          <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', display: 'flex', alignItems: 'center', gap: 0.5 }}><CalendarToday sx={{ fontSize: 14 }} /> Duration</Typography>
          <Typography sx={{ fontSize: 12, fontWeight: 700, color: C.brand }}>{fmtDurationLabel(value)}</Typography>
        </Box>
        <Box sx={{ px: 1 }}>
          <Slider value={value} min={DURATION_MIN} max={DURATION_MAX} step={DURATION_STEP} marks={DURATION_MARKS}
            valueLabelDisplay="auto" valueLabelFormat={fmtDurationLabel}
            onChange={(e, v) => onChange(v)} sx={{ color: C.brand }} />
        </Box>
      </Box>
    );
  }
  renderReminderSlider(value, onChange) {
    return (
      <Box>
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 0.5 }}>
          <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', display: 'flex', alignItems: 'center', gap: 0.5 }}><NotificationsNone sx={{ fontSize: 14 }} /> Reminder</Typography>
          <Typography sx={{ fontSize: 12, fontWeight: 700, color: C.brand }}>{fmtReminderLabel(value)}</Typography>
        </Box>
        <Box sx={{ px: 1 }}>
          <Slider value={value} min={REMINDER_MIN} max={REMINDER_MAX} step={REMINDER_STEP} marks={REMINDER_MARKS}
            valueLabelDisplay="auto" valueLabelFormat={fmtReminderLabel}
            onChange={(e, v) => onChange(v)} sx={{ color: C.brand }} />
        </Box>
      </Box>
    );
  }

  renderDropDialog() {
    const { dropDialogOpen, dropPendingOffer, dropPendingDay, dropPendingFromSlotId, dropTime, dropDuration, dropReminder, dropVisitType, dropConflict, dropReason } = this.state;
    if (!dropDialogOpen) return null;
    const isIP   = dropVisitType === 'In-person';
    const isEdit = Boolean(dropPendingFromSlotId);
    return (
      <Dialog open={dropDialogOpen} onClose={this.cancelDrop} maxWidth="xs" fullWidth
        PaperProps={{ sx: { mx: { xs: 1, sm: 3 }, width: { xs: 'calc(100% - 16px)', sm: 'auto' } } }}>
        <DialogTitle sx={{ pb: 0.5 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            {isIP ? <LocationOn sx={{ color: C.sysBadgeText, fontSize: 20 }} /> : <Phone sx={{ color: '#1a5276', fontSize: 20 }} />}
            <Box>
              <Typography fontWeight={700} sx={{ fontSize: 14, lineHeight: 1.3 }}>{isEdit ? 'Edit Schedule' : 'Schedule Visit'}</Typography>
              {dropPendingOffer && <Typography variant="caption" color="text.secondary">{dropPendingOffer.name} · {dropPendingDay}</Typography>}
            </Box>
          </Box>
        </DialogTitle>
        <DialogContent sx={{ pt: 1 }}>
          <Stack spacing={2.2} sx={{ mt: 1 }}>
            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.5, display: 'flex', alignItems: 'center', gap: 0.5 }}><CalendarToday sx={{ fontSize: 14 }} /> Day</Typography>
              <FormControl fullWidth size="small">
                <Select value={dropPendingDay} onChange={(e) => this.setState({ dropPendingDay: e.target.value, dropConflict: '' })}>
                  {this.selectableWeekDays().map((d) => <MenuItem key={d.day} value={d.day}>{DAY_FULL[d.day].charAt(0) + DAY_FULL[d.day].slice(1).toLowerCase()}, {d.month} {d.date}</MenuItem>)}
                </Select>
              </FormControl>
            </Box>
            {isEdit && (
              <Box>
                <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.5, display: 'flex', alignItems: 'center', gap: 0.5 }}><NotificationsNone sx={{ fontSize: 14 }} /> Reason for Reschedule</Typography>
                <FormControl fullWidth size="small">
                  <Select value={dropReason} displayEmpty onChange={(e) => this.setState({ dropReason: e.target.value })}>
                    <MenuItem value="" disabled><em>Select a reason…</em></MenuItem>
                    {RESCHEDULE_REASONS.map((r) => <MenuItem key={r} value={r}>{r}</MenuItem>)}
                  </Select>
                </FormControl>
              </Box>
            )}
            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.8 }}>Visit Type</Typography>
              <Box sx={{ display: 'flex', gap: 1 }}>
                <Box onClick={() => this.setState({ dropVisitType: 'In-person', dropConflict: '' })}
                  sx={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 0.6, py: 1, borderRadius: 1.5, cursor: 'pointer', border: '1.5px solid', borderColor: isIP ? C.inPersonBorder : '#e0e0e0', bgcolor: isIP ? C.inPersonBg : 'white' }}>
                  <LocationOn sx={{ fontSize: 16, color: isIP ? C.sysBadgeText : '#bbb' }} />
                  <Typography sx={{ fontSize: 12, fontWeight: isIP ? 700 : 400, color: isIP ? C.sysBadgeText : '#aaa' }}>In-person</Typography>
                </Box>
                <Box onClick={() => this.setState({ dropVisitType: 'Call', dropConflict: '' })}
                  sx={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 0.6, py: 1, borderRadius: 1.5, cursor: 'pointer', border: '1.5px solid', borderColor: !isIP ? C.callBorder : '#e0e0e0', bgcolor: !isIP ? C.callBg : 'white' }}>
                  <Phone sx={{ fontSize: 16, color: !isIP ? '#1a5276' : '#bbb' }} />
                  <Typography sx={{ fontSize: 12, fontWeight: !isIP ? 700 : 400, color: !isIP ? '#1a5276' : '#aaa' }}>Call</Typography>
                </Box>
              </Box>
            </Box>
            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.5, display: 'flex', alignItems: 'center', gap: 0.5 }}><AccessTime sx={{ fontSize: 14 }} /> Start Time</Typography>
              <TextField type="time" value={dropTime} onChange={(e) => this.setState({ dropTime: e.target.value, dropConflict: '' })} fullWidth size="small" InputLabelProps={{ shrink: true }} error={Boolean(dropConflict)} />
              {dropConflict && (
                <Box sx={{ mt: 1, px: 1.5, py: 1, bgcolor: '#FFF3F3', border: '1px solid #F5C6C6', borderRadius: 1.5 }}>
                  <Typography sx={{ fontSize: 11, color: '#B71C1C', lineHeight: 1.5 }}>⚠️ {dropConflict}</Typography>
                </Box>
              )}
            </Box>
            {this.renderDurationSlider(dropDuration, (v) => this.setState({ dropDuration: v, dropConflict: '' }))}
            {this.renderReminderSlider(dropReminder, (v) => this.setState({ dropReminder: v }))}
          </Stack>
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 2, gap: 1 }}>
          <Button onClick={this.cancelDrop} sx={{ textTransform: 'none', color: '#666' }}>Cancel</Button>
          <Button variant="contained" onClick={this.confirmDrop} sx={{ textTransform: 'none', bgcolor: C.brand, '&:hover': { bgcolor: '#3d35a0' }, px: 3 }}>{isEdit ? 'Update' : 'Schedule'}</Button>
        </DialogActions>
      </Dialog>
    );
  }

  // ─── Render: Add Visit dialog (name, day, type, time, duration, reminder) ────
  renderAddDialog() {
    const { addOpen, addName, addDay, addType, addTime, addDuration, addReminder, addConflict, addSaving } = this.state;
    if (!addOpen) return null;
    const isIP  = addType === 'In-person';
    const dates = this.selectableWeekDays(); // today + future only — never offer a past date
    return (
      <Dialog open={addOpen} onClose={this.cancelAdd} maxWidth="xs" fullWidth
        PaperProps={{ sx: { mx: { xs: 1, sm: 3 }, width: { xs: 'calc(100% - 16px)', sm: 'auto' } } }}>
        <DialogTitle sx={{ pb: 0.5 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <AddLocationAlt sx={{ color: C.brand, fontSize: 20 }} />
            <Typography fontWeight={700} sx={{ fontSize: 14 }}>Add Visit</Typography>
          </Box>
        </DialogTitle>
        <DialogContent sx={{ pt: 1 }}>
          <Stack spacing={2.2} sx={{ mt: 1 }}>
            <Autocomplete
              freeSolo
              fullWidth
              size="small"
              options={this.state.allClientNames}
              inputValue={addName}
              onInputChange={(e, val) => this.setState({ addName: val || '' })}
              renderInput={(params) => <TextField {...params} autoFocus label="Client name" />}
            />

            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.5, display: 'flex', alignItems: 'center', gap: 0.5 }}><CalendarToday sx={{ fontSize: 14 }} /> Day</Typography>
              <FormControl fullWidth size="small">
                <Select value={addDay} onChange={(e) => this.setState({ addDay: e.target.value, addConflict: '' })}>
                  {dates.map((d) => <MenuItem key={d.day} value={d.day}>{DAY_FULL[d.day].charAt(0) + DAY_FULL[d.day].slice(1).toLowerCase()}, {d.month} {d.date}</MenuItem>)}
                </Select>
              </FormControl>
            </Box>

            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.8 }}>Visit Type</Typography>
              <Box sx={{ display: 'flex', gap: 1 }}>
                <Box onClick={() => this.setState({ addType: 'In-person', addConflict: '' })}
                  sx={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 0.6, py: 1, borderRadius: 1.5, cursor: 'pointer', border: '1.5px solid', borderColor: isIP ? C.inPersonBorder : '#e0e0e0', bgcolor: isIP ? C.inPersonBg : 'white' }}>
                  <LocationOn sx={{ fontSize: 16, color: isIP ? C.sysBadgeText : '#bbb' }} /><Typography sx={{ fontSize: 12, fontWeight: isIP ? 700 : 400, color: isIP ? C.sysBadgeText : '#aaa' }}>In-person</Typography>
                </Box>
                <Box onClick={() => this.setState({ addType: 'Call', addConflict: '' })}
                  sx={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 0.6, py: 1, borderRadius: 1.5, cursor: 'pointer', border: '1.5px solid', borderColor: !isIP ? C.callBorder : '#e0e0e0', bgcolor: !isIP ? C.callBg : 'white' }}>
                  <Phone sx={{ fontSize: 16, color: !isIP ? '#1a5276' : '#bbb' }} /><Typography sx={{ fontSize: 12, fontWeight: !isIP ? 700 : 400, color: !isIP ? '#1a5276' : '#aaa' }}>Call</Typography>
                </Box>
              </Box>
            </Box>

            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.5, display: 'flex', alignItems: 'center', gap: 0.5 }}><AccessTime sx={{ fontSize: 14 }} /> Start Time</Typography>
              <TextField type="time" value={addTime} onChange={(e) => this.setState({ addTime: e.target.value, addConflict: '' })} fullWidth size="small" InputLabelProps={{ shrink: true }} error={Boolean(addConflict)} />
              {addConflict && (
                <Box sx={{ mt: 1, px: 1.5, py: 1, bgcolor: '#FFF3F3', border: '1px solid #F5C6C6', borderRadius: 1.5 }}>
                  <Typography sx={{ fontSize: 11, color: '#B71C1C', lineHeight: 1.5 }}>⚠️ {addConflict}</Typography>
                </Box>
              )}
            </Box>

            {this.renderDurationSlider(addDuration, (v) => this.setState({ addDuration: v, addConflict: '' }))}
            {this.renderReminderSlider(addReminder, (v) => this.setState({ addReminder: v }))}
          </Stack>
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 2, gap: 1 }}>
          <Button onClick={this.cancelAdd} disabled={addSaving} sx={{ textTransform: 'none', color: '#666' }}>Cancel</Button>
          <Button variant="contained" onClick={this.confirmAdd} disabled={addSaving} sx={{ textTransform: 'none', bgcolor: C.brand, '&:hover': { bgcolor: '#3d35a0' }, px: 3 }}>
            {addSaving ? <><CircularProgress size={15} color="inherit" />&nbsp;Saving…</> : 'Add & Save'}
          </Button>
        </DialogActions>
      </Dialog>
    );
  }

  // ─── Render: Add Client dialog (ported from CheckIn → tbl_temp_client_details) ─
  renderAddClientDialog() {
    const { acOpen, acName, acPhone, acContactPerson, acCity, acState, acRegion, acRegionsData, acRegionsLoading, acSaving } = this.state;
    if (!acOpen) return null;
    return (
      <Dialog open={acOpen} onClose={this.cancelAddClient} maxWidth="xs" fullWidth
        PaperProps={{ sx: { mx: { xs: 1, sm: 3 }, width: { xs: 'calc(100% - 16px)', sm: 'auto' } } }}>
        <DialogTitle sx={{ pb: 0.5 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <PersonAdd sx={{ color: C.brand, fontSize: 20 }} />
            <Typography fontWeight={700} sx={{ fontSize: 14 }}>Add Client</Typography>
          </Box>
        </DialogTitle>
        <DialogContent sx={{ pt: 1 }}>
          <Stack spacing={2} sx={{ mt: 1 }}>
            <TextField label="Client Name" fullWidth size="small" value={acName} onChange={(e) => this.setState({ acName: e.target.value })} />
            <TextField label="Phone Number" fullWidth size="small" value={acPhone} inputProps={{ inputMode: 'numeric', maxLength: 10 }}
              onChange={(e) => this.setState({ acPhone: e.target.value.replace(/\D/g, '').slice(0, 10) })} />
            <TextField label="Contact Person Name" fullWidth size="small" value={acContactPerson} onChange={(e) => this.setState({ acContactPerson: e.target.value })} />
            <TextField label="City" fullWidth size="small" value={acCity} onChange={(e) => this.setState({ acCity: e.target.value })} />
            <TextField label="State" fullWidth size="small" value={acState} onChange={(e) => this.setState({ acState: e.target.value })} />
            <TextField select label="Region" fullWidth size="small" value={acRegion} disabled={acRegionsLoading}
              helperText={acRegionsLoading ? 'Loading regions…' : ''}
              onChange={(e) => this.setState({ acRegion: e.target.value })}>
              {acRegionsData.map((region, idx) => <MenuItem key={idx} value={region}>{region}</MenuItem>)}
            </TextField>
          </Stack>
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 2, gap: 1 }}>
          <Button onClick={this.cancelAddClient} disabled={acSaving} sx={{ textTransform: 'none', color: '#666' }}>Cancel</Button>
          <Button variant="contained" onClick={this.saveNewClient} disabled={acSaving} sx={{ textTransform: 'none', bgcolor: C.brand, '&:hover': { bgcolor: '#3d35a0' }, px: 3 }}>
            {acSaving ? <><CircularProgress size={15} color="inherit" />&nbsp;Saving…</> : 'Save'}
          </Button>
        </DialogActions>
      </Dialog>
    );
  }

  // ─── Render: client detail sheet ────────────────────────────────────────────
  renderClientDetail() {
    const { detailClient } = this.state;
    if (!detailClient) return null;
    const STATUS_COLOR = {
      Prospect:  { bg: '#EAF3DE', color: '#27500A' },
      Pending:   { bg: '#FFF8EE', color: '#BA7517' },
      Budgetary: { bg: '#F5F5F5', color: '#555555' },
    };
    const offers  = detailClient.offers || [];
    const debtors = detailClient.debtors || [];
    const overallMf = clientOverallMf(offers);
    return (
      <Dialog open={Boolean(detailClient)} onClose={() => this.setState({ detailClient: null })} maxWidth="xs" fullWidth
        PaperProps={{ sx: { mx: { xs: 1, sm: 3 }, width: { xs: 'calc(100% - 16px)', sm: 'auto' }, borderRadius: 2, overflow: 'hidden' } }}>
        <Box sx={{ px: 2, py: 1.5, bgcolor: C.brand, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, minWidth: 0 }}>
            <Business sx={{ color: 'white', fontSize: 20, flexShrink: 0 }} />
            <Box sx={{ minWidth: 0 }}>
              <Typography sx={{ fontSize: 13, fontWeight: 700, color: 'white', lineHeight: 1.3 }} noWrap>{detailClient.name}</Typography>
              <Typography sx={{ fontSize: 10.5, color: 'rgba(255,255,255,0.8)' }}>
                {offers.length} offer{offers.length !== 1 ? 's' : ''}{detailClient.totalValueFormatted ? ` · ${detailClient.totalValueFormatted}` : ''}
                {overallMf > 0 ? ` · MF ${overallMf.toFixed(2)}` : ''}
                {debtors.length > 0 && detailClient.totalDebtorAmountFormatted ? ` · ${detailClient.totalDebtorAmountFormatted} due` : ''}
              </Typography>
            </Box>
          </Box>
          <IconButton size="small" onClick={() => this.setState({ detailClient: null })} sx={{ color: 'white', p: '4px' }}><Close sx={{ fontSize: 16 }} /></IconButton>
        </Box>
        <Box sx={{ maxHeight: 380, overflowY: 'auto' }}>
          {offers.length === 0 && debtors.length === 0 && (
            <Typography sx={{ fontSize: 11, color: '#aaa', textAlign: 'center', py: 3 }}>No offer / debtor details.</Typography>
          )}
          {offers.map((offer, idx) => {
            const sc = STATUS_COLOR[offer.status] || STATUS_COLOR.Budgetary;
            return (
              <Box key={offer.id || idx}>
                <Box sx={{ px: 2, py: 1.2 }}>
                  <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 0.4 }}>
                    <Typography sx={{ fontSize: 10.5, fontWeight: 700, color: '#333' }} noWrap>{offer.offerNo}</Typography>
                    <Chip label={offer.status} size="small" sx={{ height: 17, fontSize: 9.5, fontWeight: 600, bgcolor: sc.bg, color: sc.color, '& .MuiChip-label': { px: 0.8 } }} />
                  </Box>
                  <Typography sx={{ fontSize: 11, color: '#444', lineHeight: 1.4 }}>{offer.name}</Typography>
                  <Box sx={{ display: 'flex', gap: 2, mt: 0.6, flexWrap: 'wrap' }}>
                    <Box>
                      <Typography sx={{ fontSize: 9, color: '#aaa', textTransform: 'uppercase' }}>Value</Typography>
                      <Typography sx={{ fontSize: 11, fontWeight: 700, color: C.brand }}>{offer.valueFormatted}</Typography>
                    </Box>
                    {offer.mf > 0 && (
                      <Box>
                        <Typography sx={{ fontSize: 9, color: '#aaa', textTransform: 'uppercase' }}>MF</Typography>
                        <Typography sx={{ fontSize: 11, fontWeight: 700, color: '#1565C0' }}>{offer.mfFormatted || offer.mf}</Typography>
                      </Box>
                    )}
                    {offer.expectedDate && (
                      <Box>
                        <Typography sx={{ fontSize: 9, color: '#aaa', textTransform: 'uppercase' }}>Expected</Typography>
                        <Typography sx={{ fontSize: 11, color: '#444' }}>{new Date(offer.expectedDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</Typography>
                      </Box>
                    )}
                    {offer.reminderDate && (
                      <Box>
                        <Typography sx={{ fontSize: 9, color: '#aaa', textTransform: 'uppercase' }}>Reminder</Typography>
                        <Typography sx={{ fontSize: 11, color: offer.isOverdue ? C.high : '#444' }}>{new Date(offer.reminderDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}{offer.isOverdue ? ' · Overdue' : ''}</Typography>
                      </Box>
                    )}
                  </Box>
                </Box>
                {idx < offers.length - 1 && <Divider />}
              </Box>
            );
          })}
          {debtors.length > 0 && (
            <Box>
              <Box sx={{ px: 2, py: 1, bgcolor: '#FFF5F5', borderTop: '2px solid #e0e0e0', display: 'flex', alignItems: 'center', gap: 1 }}>
                <Typography sx={{ fontSize: 10, fontWeight: 700, color: '#B71C1C', textTransform: 'uppercase' }}>Debtors</Typography>
                {detailClient.totalDebtorAmountFormatted && <Chip label={detailClient.totalDebtorAmountFormatted} size="small" sx={{ height: 16, fontSize: 9.5, fontWeight: 700, bgcolor: '#FEEDED', color: '#B71C1C', border: '1px solid #F5C6C6', '& .MuiChip-label': { px: 0.8 } }} />}
              </Box>
              {debtors.map((d, idx) => (
                <Box key={d.invoiceno || idx}>
                  <Box sx={{ px: 2, py: 1.2, bgcolor: d.isOverdue ? '#FFFAFA' : 'white' }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 0.4 }}>
                      <Typography sx={{ fontSize: 10.5, fontWeight: 700, color: '#333' }}>{d.invoiceno}</Typography>
                      {d.isOverdue && <Chip label={`${d.overdue_days}d overdue`} size="small" sx={{ height: 17, fontSize: 9.5, fontWeight: 600, bgcolor: '#FEEDED', color: '#B71C1C', border: '1px solid #F5C6C6', '& .MuiChip-label': { px: 0.8 } }} />}
                    </Box>
                    {d.projectName ? <Typography sx={{ fontSize: 11, color: '#444' }}>{d.projectName}</Typography> : null}
                    <Box sx={{ display: 'flex', gap: 2, mt: 0.6 }}>
                      <Box>
                        <Typography sx={{ fontSize: 9, color: '#aaa', textTransform: 'uppercase' }}>Amount</Typography>
                        <Typography sx={{ fontSize: 11, fontWeight: 700, color: '#B71C1C' }}>{d.invoiceAmountFmt}</Typography>
                      </Box>
                      {d.paymentduedate && (
                        <Box>
                          <Typography sx={{ fontSize: 9, color: '#aaa', textTransform: 'uppercase' }}>Due</Typography>
                          <Typography sx={{ fontSize: 11, color: d.isOverdue ? '#B71C1C' : '#444' }}>{new Date(d.paymentduedate).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</Typography>
                        </Box>
                      )}
                    </Box>
                  </Box>
                  {idx < debtors.length - 1 && <Divider />}
                </Box>
              ))}
            </Box>
          )}
        </Box>
      </Dialog>
    );
  }

  // ─── Render: bottom bar ─────────────────────────────────────────────────────
  renderBottomBar() {
    const { planSaving, planStatus, marking, attendanceMarked } = this.state;
    const { total, visits, calls, unscheduled } = this.getStats();
    return (
      <Paper elevation={3} sx={{ borderRadius: 0, flexShrink: 0, zIndex: 3, borderTop: '1px solid #e0e0e0' }}>
        <Box sx={{ px: 1.5, pt: 0.8, display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: 0.5 }}>
          <Typography sx={{ fontSize: 11, color: '#555' }}>
            <b>{total}</b> scheduled · <b>{visits}</b> visits · <b>{calls}</b> calls · <b style={{ color: C.high }}>{unscheduled}</b> <span style={{ color: C.high }}>unscheduled</span>
          </Typography>
        </Box>
        <Box sx={{ px: 1.5, py: 1, display: 'flex', gap: 1 }}>
          <Button variant="outlined" size="small" startIcon={marking ? <CircularProgress size={14} color="inherit" /> : <HowToReg fontSize="small" />} onClick={this.confirmMarkAttendance} disabled={marking}
            sx={{ textTransform: 'none', fontSize: 12, minHeight: 40, flex: 1,
              borderColor: attendanceMarked ? C.low : C.pendingAccent,
              color: attendanceMarked ? C.low : C.pendingAccent,
              bgcolor: attendanceMarked ? 'rgba(29,158,117,0.08)' : 'rgba(214,69,69,0.06)',
              '&:hover': { borderColor: attendanceMarked ? C.low : C.pendingAccent, bgcolor: attendanceMarked ? 'rgba(29,158,117,0.14)' : 'rgba(214,69,69,0.12)' } }}>
            {attendanceMarked ? 'Marked' : 'Attendance'}
          </Button>
          <Button variant="outlined" size="small" onClick={this.saveDraft} disabled={planSaving}
            sx={{ textTransform: 'none', borderColor: '#bbb', color: '#444', fontSize: 12, minHeight: 40, flex: 1 }}>{planSaving ? 'Saving…' : 'Save draft'}</Button>
          <Button variant="contained" size="small" onClick={this.confirmSubmitToRM} disabled={planSaving || planStatus === 'Submitted' || planStatus === 'Approved'}
            sx={{ textTransform: 'none', bgcolor: C.brand, '&:hover': { bgcolor: '#3d35a0' }, fontSize: 12, minHeight: 40, flex: 1.4 }}>Submit to RM</Button>
        </Box>
      </Paper>
    );
  }

  // ─── Render: Reminders dialog — every offer/debtor with a reminder_date set,
  // grouped by client, each with Reschedule / Close actions. Mirrors the main
  // web app's SalesVisitPlanning.js Reminders dialog.
  renderRemindersDialog() {
    const { remindersDialog } = this.state;
    if (!remindersDialog.open) return null;
    const fmtDate = (d) => d ? new Date(d).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }) : '—';

    const reminderRow = (r, key, label, type, clientId, clientName) => {
      const item = { type, clientId, clientName, refNo: r.offerNo || r.invoiceNo, reminderDate: r.reminderDate, nextAction: r.nextAction, remarks: r.remarks };
      return (
        <Box key={key} sx={{ px: 1.2, py: 1, borderRadius: 1.5, bgcolor: r.overdue ? '#FEEDED' : '#fafafa', border: `1px solid ${r.overdue ? '#F5C6C6' : '#e8e8e8'}`, mb: 0.8 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 0.3 }}>
            <Typography sx={{ fontSize: 11, fontWeight: 700, color: '#333' }}>{label}</Typography>
            <Chip
              label={fmtDate(r.reminderDate) + (r.overdue ? ' · Overdue' : '')}
              size="small"
              sx={{ height: 18, fontSize: 10, fontWeight: 700, bgcolor: r.overdue ? '#FEEDED' : '#EEEAFF', color: r.overdue ? '#B71C1C' : C.brand, border: `1px solid ${r.overdue ? '#F5C6C6' : '#DCD7F2'}`, '& .MuiChip-label': { px: 0.8 } }}
            />
          </Box>
          {r.projectName && <Typography sx={{ fontSize: 11, color: '#555', mb: 0.3 }}>{r.projectName}</Typography>}
          {r.valueFormatted && <Typography sx={{ fontSize: 10.5, color: '#777', mb: 0.3 }}>Value: <b style={{ color: C.brand }}>{r.valueFormatted}</b>{r.status ? ` · ${r.status}` : ''}</Typography>}
          {r.invoiceAmountFormatted && <Typography sx={{ fontSize: 10.5, color: '#777', mb: 0.3 }}>Amount: <b style={{ color: '#B71C1C' }}>{r.invoiceAmountFormatted}</b>{r.overdueDays > 0 ? ` · ${r.overdueDays}d overdue` : ''}</Typography>}
          {r.nextAction && <Typography sx={{ fontSize: 10.5, color: '#444', fontStyle: 'italic' }}>Next action: {r.nextAction}</Typography>}
          {r.remarks && <Typography sx={{ fontSize: 10.5, color: '#888', mt: 0.2 }}>Remarks: {r.remarks}</Typography>}
          <Box sx={{ display: 'flex', gap: 0.8, mt: 0.8 }}>
            <Button size="small" variant="outlined" onClick={() => this.openRescheduleReminder(item)}
              sx={{ textTransform: 'none', fontSize: 10.5, py: 0.2, px: 1, minWidth: 0, borderColor: C.brand, color: C.brand }}>
              Reschedule
            </Button>
            <Button size="small" variant="outlined" onClick={() => this.closeReminderItem(item)}
              sx={{ textTransform: 'none', fontSize: 10.5, py: 0.2, px: 1, minWidth: 0, borderColor: '#bbb', color: '#666' }}>
              Close
            </Button>
          </Box>
        </Box>
      );
    };

    return (
      <Dialog open onClose={this.closeReminders} maxWidth="sm" fullWidth>
        <DialogTitle sx={{ bgcolor: C.med, color: '#fff', py: 1.4, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <Typography fontWeight={700} fontSize={15}>Reminders</Typography>
          <IconButton size="small" onClick={this.closeReminders} sx={{ color: '#fff' }}><Close fontSize="small" /></IconButton>
        </DialogTitle>
        <DialogContent dividers sx={{ maxHeight: 480 }}>
          {remindersDialog.loading ? (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, py: 3, justifyContent: 'center' }}>
              <CircularProgress size={20} /><Typography variant="body2" color="text.secondary">Loading reminders…</Typography>
            </Box>
          ) : remindersDialog.error ? (
            <Typography variant="body2" color="text.secondary">{remindersDialog.error}</Typography>
          ) : remindersDialog.clients.length === 0 ? (
            <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', py: 3 }}>No reminders set on any offer or debtor.</Typography>
          ) : (
            remindersDialog.clients.map((c, ci) => (
              <Box key={c.clientId} sx={{ mb: 2 }}>
                <Typography sx={{ fontSize: 12.5, fontWeight: 700, color: '#222', mb: 0.8 }}>{c.clientName}</Typography>
                {c.offerReminders.map((r, i) => reminderRow(r, `o_${i}`, r.offerNo, 'offer', c.clientId, c.clientName))}
                {c.debtorReminders.map((r, i) => reminderRow(r, `d_${i}`, r.invoiceNo, 'debtor', c.clientId, c.clientName))}
                {ci < remindersDialog.clients.length - 1 && <Divider sx={{ mt: 1.5 }} />}
              </Box>
            ))
          )}
        </DialogContent>
        <DialogActions sx={{ px: 2, py: 1 }}>
          <Button onClick={this.closeReminders} sx={{ textTransform: 'none', color: C.brand }}>Close</Button>
        </DialogActions>
      </Dialog>
    );
  }

  // Small date-picker sub-dialog for the "Reschedule" action on a single
  // offer/debtor reminder (opened from renderRemindersDialog above).
  renderRescheduleReminderDialog() {
    const { rescheduleReminder } = this.state;
    if (!rescheduleReminder.open) return null;
    const { item, newDate, saving } = rescheduleReminder;
    return (
      <Dialog open onClose={saving ? undefined : this.closeRescheduleReminder} maxWidth="xs" fullWidth>
        <DialogTitle sx={{ py: 1.4 }}>
          <Typography fontWeight={700} fontSize={15}>Reschedule reminder</Typography>
          <Typography variant="caption" color="text.secondary">{item && item.refNo}</Typography>
        </DialogTitle>
        <DialogContent dividers>
          <TextField
            label="New reminder date" type="date" fullWidth
            InputLabelProps={{ shrink: true }}
            value={newDate}
            onChange={(e) => this.setState((s) => ({ rescheduleReminder: { ...s.rescheduleReminder, newDate: e.target.value } }))}
            sx={{ mt: 0.5 }}
          />
        </DialogContent>
        <DialogActions sx={{ px: 2, py: 1 }}>
          <Button onClick={this.closeRescheduleReminder} disabled={saving} sx={{ textTransform: 'none', color: '#444' }}>Cancel</Button>
          <Button variant="contained" onClick={this.confirmRescheduleReminder} disabled={saving || !newDate}
            sx={{ textTransform: 'none', bgcolor: C.brand, '&:hover': { bgcolor: '#3d35a0' } }}>
            {saving ? 'Saving…' : 'Reschedule'}
          </Button>
        </DialogActions>
      </Dialog>
    );
  }

  render() {
    if (this.state.LogoutFlag) return <LoggedOut />;
    const { queueLoading, queueError } = this.state;
    return (
      <Box sx={{ display: 'flex', flexDirection: 'column', height: '100vh', bgcolor: '#f5f6f8', overflow: 'hidden', maxWidth: 640, mx: 'auto' }}>
        {this.renderTopBar()}
        {this.renderDayStrip()}
        <Box sx={{ flex: 1, overflowY: 'auto', px: 1.5, py: 1.2 }}>
          {queueLoading ? (
            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', mt: 5, gap: 1 }}>
              <CircularProgress size={26} sx={{ color: C.brand }} />
              <Typography sx={{ fontSize: 12, color: '#aaa' }}>Loading your plan…</Typography>
            </Box>
          ) : (
            <>
              {this.renderDaySections()}
              {queueError
                ? <Box sx={{ textAlign: 'center', mt: 2 }}>
                    <Typography sx={{ fontSize: 11, color: C.high, mb: 1 }}>{queueError}</Typography>
                    <Button size="small" onClick={this.loadClientQueue} sx={{ fontSize: 11, textTransform: 'none', color: C.brand }}>Retry</Button>
                  </Box>
                : this.renderUnscheduled()}
            </>
          )}
        </Box>
        {this.renderBottomBar()}
        {this.renderDropDialog()}
        {this.renderAddDialog()}
        {this.renderAddClientDialog()}
        {this.renderClientDetail()}
        {this.renderRemindersDialog()}
        {this.renderRescheduleReminderDialog()}
        <ConfirmDialog
          open={this.state.confirm.open}
          title={this.state.confirm.title}
          message={this.state.confirm.message}
          confirmLabel={this.state.confirm.confirmLabel}
          cancelLabel={this.state.confirm.cancelLabel}
          danger={this.state.confirm.danger}
          onConfirm={this.handleConfirm}
          onCancel={this.closeConfirm}
        />
        <Snackbar open={this.state.SnackBar} autoHideDuration={this.state.SnackbarTimeOut}
          onClose={() => this.setState({ SnackBar: false })} anchorOrigin={{ vertical: 'top', horizontal: 'center' }}>
          <Alert onClose={() => this.setState({ SnackBar: false })} severity={this.state.SnackBarVariant} sx={{ width: '100%' }}>{this.state.snackBarMessage}</Alert>
        </Snackbar>
      </Box>
    );
  }
}

export default MyVisitPlan;
